def natural_sort_strings(strings):
    keys = []
    for s in strings:
        parts = []
        i = 0
        while i < len(s):
            if s[i].isdigit():
                j = i
                while j < len(s) and s[j].isdigit():
                    j += 1
                parts.append(('N', int(s[i:j])))
                i = j
            else:
                j = i
                while j < len(s) and not s[j].isdigit():
                    j += 1
                parts.append(('T', s[i:j]))
                i = j
        keys.append(parts)
    def compare_keys(a, b):
        n = min(len(a), len(b))
        for idx in range(n):
            ka, kb = a[idx], b[idx]
            if ka[0] != kb[0]:
                return -1 if ka[0] == 'T' else 1
            if ka[0] == 'T':
                if ka[1] < kb[1]:
                    return -1
                elif ka[1] > kb[1]:
                    return 1
            else:
                if ka[1] < kb[1]:
                    return -1
                elif ka[1] > kb[1]:
                    return 1
        if len(a) < len(b):
            return -1
        elif len(a) > len(b):
            return 1
        return 0
    import functools
    @functools.cmp_to_key
    def sort_key(s):
        return keys[strings.index(s)]
    result = sorted(strings, key=sort_key)
    return result
